// 定义枚举
enum Status {
  pending,    // 待处理
  approved,   // 已批准
  rejected,   // 已拒绝
  cancelled,  // 已取消
}

void main() {
  // 使用枚举值
  Status currentStatus = Status.pending;
  print('当前状态: $currentStatus');

  // 通过 .index 获取索引（从 0 开始）
  print('索引值: ${currentStatus.index}');  // 0

  // 通过 .values 获取所有枚举值
  print('所有状态: ${Status.values}');

  // 遍历所有枚举值
  for (var status in Status.values) {
    print('RUNOOB 状态: $status, 索引: ${status.index}');
  }

  // 通过字符串获取枚举值
  Status parsed = Status.values.byName('approved');
  print('解析出的状态: $parsed');

  // 在 switch 中使用枚举
  switch (currentStatus) {
    case Status.pending:
      print('订单待处理');
      break;
    case Status.approved:
      print('订单已批准');
      break;
    case Status.rejected:
      print('订单被拒绝');
      break;
    case Status.cancelled:
      print('订单已取消');
      break;
  }
}

void main() {
  // 基本的 try-catch
  try {
    int result = 10 ~/ 0;  // 除零操作会抛出异常
    print('结果: $result');  // 这行不会执行
  } catch (e) {
    // e 是异常对象
    print('捕获到异常: $e');
  }

  // 获取异常和堆栈信息
  try {
    List<int> numbers = [1, 2, 3];
    print(numbers[10]);  // 访问越界索引
  } catch (e, stackTrace) {
    // e 是异常，stackTrace 是调用堆栈
    print('RUNOOB 异常: $e');
    print('堆栈信息:\n$stackTrace');
  }

  // finally：无论是否异常都会执行
  try {
    print('尝试执行操作...');
    int result = 5 ~/ 0;
    print('这行不会执行: $result');
  } catch (e) {
    print('出错: $e');
  } finally {
    // finally 块中的代码始终执行，常用于清理资源
    print('清理资源完成（finally 总是执行）');
  }
}

