// 父类（基类、超类）
class Animal {
  String name;

  Animal(this.name);

  void eat() {
    print('$name 在吃东西');
  }

  void sleep() {
    print('$name 在睡觉');
  }
}

// 子类：使用 extends 继承 Animal
class Dog extends Animal {
  String breed;  // 品种

  // 子类构造函数需要调用父类构造函数
  Dog(String name, this.breed) : super(name);

  // 子类新增的方法
  void bark() {
    print('$name（$breed）在汪汪叫！');
  }
}

void main() {
  var dog = Dog('旺财', '金毛');

  // 调用从父类继承的方法
  dog.eat();
  dog.sleep();

  // 调用子类自己的方法
  dog.bark();

  // 子类对象也是父类类型
  Animal animal = dog;  // Dog 是 Animal，可以向上转型
  animal.eat();
}

